# ==============================================================================# 046_PRIORITY_ENGINE.py# ==============================================================================import sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")# ==============================================================================# PRIORITY QUEUE# ==============================================================================cur.execute("""CREATE TABLE IF NOT EXISTS priority_queue(    id INTEGER PRIMARY KEY AUTOINCREMENT,    created_at TEXT,    source TEXT,    source_id INTEGER,    name TEXT,    priority TEXT,    score INTEGER,    status TEXT)""")conn.commit()# ==============================================================================# LIMPA FILA ANTIGA# ==============================================================================cur.execute("DELETE FROM priority_queue")conn.commit()# ==============================================================================# MAPA DE PRIORIDADES# ==============================================================================SCORES = {    "CRITICAL":100,    "HIGH":75,    "NORMAL":50,    "LOW":25,    "INFO":10}# ==============================================================================# COMMAND BUS# ==============================================================================cur.execute("""SELECTid,command_name,priority,statusFROM command_history""")for row in cur.fetchall():    cur.execute("""    INSERT INTO priority_queue(        created_at,        source,        source_id,        name,        priority,        score,        status    )    VALUES(?,?,?,?,?,?,?)    """,(        datetime.now().isoformat(),        "COMMAND",        row["id"],        row["command_name"],        row["priority"],        SCORES.get(row["priority"],0),        row["status"]    ))# ==============================================================================# TASKS# ==============================================================================cur.execute("""SELECTid,task_name,priority,statusFROM task_queue""")for row in cur.fetchall():    cur.execute("""    INSERT INTO priority_queue(        created_at,        source,        source_id,        name,        priority,        score,        status    )    VALUES(?,?,?,?,?,?,?)    """,(        datetime.now().isoformat(),        "TASK",        row["id"],        row["task_name"],        row["priority"],        SCORES.get(row["priority"],0),        row["status"]    ))# ==============================================================================# RULES# ==============================================================================cur.execute("""SELECTid,rule_name,priority,statusFROM rule_engine""")for row in cur.fetchall():    cur.execute("""    INSERT INTO priority_queue(        created_at,        source,        source_id,        name,        priority,        score,        status    )    VALUES(?,?,?,?,?,?,?)    """,(        datetime.now().isoformat(),        "RULE",        row["id"],        row["rule_name"],        row["priority"],        SCORES.get(row["priority"],0),        row["status"]    ))conn.commit()# ==============================================================================# OUTPUT# ==============================================================================print("="*80)print("PRIORITY ENGINE")print("="*80)cur.execute("""SELECTsource,name,priority,score,statusFROM priority_queueORDER BYscore DESC,id""")rows = cur.fetchall()for row in rows:    print(        f"{row['score']:03d} "        f"{row['priority']:<9}"        f"{row['source']:<10}"        f"{row['name']:<30}"        f"{row['status']}"    )print("="*80)cur.execute("""SELECT COUNT(*)FROM priority_queue""")print("ITENS PRIORIZADOS:", cur.fetchone()[0])print("="*80)conn.close()

